/* LCARS Red Alert. Back to normal: switch theme to lcars. Disable: switch theme to t3-code. */
:root{--lc-orange:#FF2222;--lc-peach:#FFB3B3;--lc-lav:#B33A3A;--lc-violet:#FF4444;--lc-blue:#FFAAAA;--lc-gold:#FF6666;--lc-font:"LCARS Antonio","Avenir Next Condensed","Arial Narrow",sans-serif;}
::selection{background:color-mix(in srgb,var(--lc-lav) 38%,transparent);}

