[data-slot="sidebar"],[data-slot="sidebar-gap"],[data-slot="sidebar-container"],[data-slot="sidebar-inset"],[data-workspace-area="conversation"]{background:transparent !important;border-color:transparent !important;box-shadow:none !important;}
/* Every container that wraps the chat (whatever the app calls it) is see-through, except the root that holds the stars */
:is(*:has([data-workspace-area="conversation"])):not(html):not(body):not([data-slot="sidebar-wrapper"]){background-color:transparent !important;background-image:none !important;}
/* Forward warp, star-zoom: two star layers grow outward from the centre, brighten, then fade, half a cycle apart */
@property --lc-wv{syntax:"<number>";inherits:true;initial-value:0;}
@keyframes lc-zoom{0%{transform:scale(1);opacity:0}30%{opacity:var(--lc-wv)}100%{transform:scale(3.4);opacity:0}}
[data-workspace-area="conversation"]{--lc-wv:0;transition:--lc-wv 1.5s ease;isolation:isolate;overflow:clip;}
[data-workspace-area="conversation"]::before,[data-workspace-area="conversation"]::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:0;background-repeat:repeat;background-position:center;transform-origin:50% 50%;animation:lc-zoom 2s cubic-bezier(.5,0,1,.6) infinite paused;}
