/* Sidebar elbow: lavender upright sweeping into an orange base bar */
[data-slot="sidebar-inner"]{border-right:12px solid var(--lc-lav) !important;border-bottom:24px solid var(--lc-orange) !important;border-bottom-right-radius:48px !important;}
[data-sidebar-row]{border-radius:14px !important;}
