[data-chat-header]{font-family:var(--lc-font) !important;font-size:15px;text-transform:uppercase;letter-spacing:.06em;border-bottom:6px solid transparent !important;border-image:linear-gradient(90deg,var(--lc-orange) 0 40%,#000 40% 40.6%,var(--lc-peach) 40.6% 60%,#000 60% 60.6%,var(--lc-lav) 60.6% 82%,#000 82% 82.6%,var(--lc-violet) 82.6% 100%) 1 !important;}

/* Controls: pills */
[data-slot="button"],[data-slot="select-trigger"]{border-radius:999px !important;}
[data-slot="input"]{border-radius:14px !important;}

/* Messages */
[data-user-message-bubble]{border-radius:16px 4px 4px 16px !important;border-right:10px solid var(--lc-lav) !important;}
[data-message-role="assistant"] .chat-markdown{border-left:6px solid var(--lc-violet);padding:12px 18px 12px 16px;background:rgba(18,16,30,.92);border:0;border-left:6px solid var(--lc-violet);border-radius:0 16px 16px 0;}
[data-timeline-row-kind="work"]{background:transparent;}
/* No divider rule under "Worked for..." */
[data-timeline-row-kind="work"],[data-timeline-row-kind="work"] *{border-color:transparent !important;}
[data-timeline-row-kind] :is(.h-px,hr){background:transparent !important;border-color:transparent !important;}
/* Markdown rules (---) in messages and the composer: an LCARS bar, not the hidden divider above */
[data-timeline-row-kind] :is(.chat-markdown,.composer-tiptap) hr,[data-slot="composer-host"] :is(.chat-markdown,.composer-tiptap) hr,:is(.chat-markdown,.composer-tiptap) hr{display:block !important;height:4px !important;border:0 !important;border-radius:999px !important;margin:.9rem 0 !important;opacity:1 !important;background-image:linear-gradient(90deg,var(--lc-orange) 0 18%,transparent 18% 19.5%,var(--lc-lav) 19.5% 100%) !important;}
