/* Elbow corner: while the bottom terminal is open, the notch outside the sidebar's curve is the same smoked glass */
[data-slot="sidebar-container"]{border-right-width:0 !important;}
[data-slot="sidebar-container"]::after{content:"";position:absolute;right:0;bottom:0;width:48px;height:48px;z-index:-1;pointer-events:none;background:var(--lc-term-glass);opacity:0;transition:opacity .2s ease;}
:root:has([data-terminal-owner="drawer"]) [data-slot="sidebar-container"]::after{opacity:1;}
@media (prefers-reduced-motion:reduce){[data-thread-terminal-drawer]{animation:none !important;}[data-thread-terminal-drawer]::before,[data-thread-terminal-drawer]::after{display:none !important;}}

/* Scrollbars */
::-webkit-scrollbar{width:10px;height:10px;background:transparent;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--lc-lav) 60%,transparent);border-radius:999px;}
::-webkit-scrollbar-thumb:hover{background:var(--lc-orange);}
[data-slot="scroll-area-thumb"]{background:color-mix(in srgb,var(--lc-lav) 60%,transparent) !important;}
[data-slot="scroll-area-thumb"]:hover{background:var(--lc-orange) !important;}

/* Image attachments: LCARS viewscreen frame matching the user bubble */
[data-message-role="user"] :has(> button[aria-label^="Preview "]){background:#120505 !important;border:2px solid var(--lc-lav) !important;border-right-width:10px !important;border-radius:16px 4px 4px 16px !important;padding:6px !important;box-shadow:inset 0 -4px 0 #000, 0 0 0 0 transparent;transition:border-color .15s;}
[data-message-role="user"] :has(> button[aria-label^="Preview "]):hover{border-color:var(--lc-orange) !important;}
[data-message-role="user"] button[aria-label^="Preview "]{border-radius:10px 2px 2px 10px !important;overflow:hidden;}

/* Composer @ / slash autocomplete.
   The app paints the active row with a layered !important utility, so recolor it through its variables. */
[data-composer-command-drawer]{background:#0A0303 !important;}
[data-composer-item-id]{opacity:1 !important;border-radius:14px 4px 4px 14px !important;}
[data-composer-item-id]:not([data-active]){color:#FFE6E6 !important;}
[data-composer-item-id]:not([data-active]) svg{color:var(--lc-violet) !important;}
[data-composer-item-id]:not([data-active]):hover{background:#200808 !important;}
[data-composer-item-id][data-active]{--accent:#FF2222;--color-accent:#FF2222;--accent-foreground:#000;--contrast-accent-foreground:#000;--color-accent-foreground:#000;--foreground:#000;--color-foreground:#000;--secondary-label:#000;--color-secondary-label:#000;--muted-foreground:#000;--color-muted-foreground:#000;background:#FF2222 !important;color:#000 !important;box-shadow:inset -8px 0 0 #990000;}
[data-composer-item-id][data-active],[data-composer-item-id][data-active] *{--app-theme-secondary-label:#000;--info-foreground:#000;--secondary-label:#000;--muted-foreground:#000;}
[data-composer-item-id][data-active] *,[data-composer-item-id][data-active] svg{color:#000 !important;opacity:1 !important;}

/* Working threads: two LCARS bar meters that jump back and forth + an endcap that swaps colors in hard steps */
@property --lc-a{syntax:"<percentage>";inherits:false;initial-value:30%;}
@property --lc-b{syntax:"<percentage>";inherits:false;initial-value:60%;}
@keyframes lc-meter-a{0%{--lc-a:22%}14%{--lc-a:58%}28%{--lc-a:34%}42%{--lc-a:76%}57%{--lc-a:46%}71%{--lc-a:88%}85%{--lc-a:30%}100%{--lc-a:22%}}
@keyframes lc-meter-b{0%{--lc-b:64%}17%{--lc-b:40%}33%{--lc-b:82%}50%{--lc-b:52%}67%{--lc-b:70%}83%{--lc-b:26%}100%{--lc-b:64%}}
@keyframes lc-cap-cycle{0%,49.9%{box-shadow:inset -8px 0 0 #FF2222}50%,100%{box-shadow:inset -8px 0 0 #7A0000}}
@keyframes lc-cap-cycle-sel{0%,49.9%{box-shadow:inset -8px 0 0 #990000}50%,100%{box-shadow:inset -8px 0 0 #FF6060}}
[data-sidebar-row]:has(.text-info-foreground){
 background-image:linear-gradient(90deg,#FF8080 0 18px,#FF2222 18px),linear-gradient(90deg,#B33A3A 0 18px,#FF4444 18px),repeating-linear-gradient(90deg,#FFFFFF22 0 1px,transparent 1px 12.5%) !important;
 background-size:var(--lc-a) 2px,var(--lc-b) 2px,calc(100% - 28px) 6px !important;
 background-position:14px calc(100% - 6px),14px calc(100% - 2px),14px calc(100% - 1px) !important;
 background-repeat:no-repeat !important;
 animation:lc-meter-a 3.2s steps(4,jump-none) infinite,lc-meter-b 2.6s steps(3,jump-none) infinite,lc-cap-cycle 1.6s infinite !important;}
[data-sidebar-row][aria-current]:not([aria-current="false"]):has(.text-info-foreground){
 background-color:var(--lc-orange) !important;
 background-image:linear-gradient(90deg,#7A0000 0 18px,#000 18px),linear-gradient(90deg,#7A0000 0 18px,#4A0000 18px),repeating-linear-gradient(90deg,#00000033 0 1px,transparent 1px 12.5%) !important;
 background-size:var(--lc-a) 2px,var(--lc-b) 2px,calc(100% - 28px) 6px !important;
 background-position:14px calc(100% - 6px),14px calc(100% - 2px),14px calc(100% - 1px) !important;
 background-repeat:no-repeat !important;
 animation:lc-meter-a 3.2s steps(4,jump-none) infinite,lc-meter-b 2.6s steps(3,jump-none) infinite,lc-cap-cycle-sel 1.6s infinite !important;}
@media (prefers-reduced-motion:reduce){[data-sidebar-row]:has(.text-info-foreground),[data-sidebar-row][aria-current][aria-current]:not([aria-current="false"]):has(.text-info-foreground){animation:none !important;}}

/* Waiting threads: LCARS standby - alternating cells swap in hard steps, slow violet endcap blink */
@property --lc-c1{syntax:"<color>";inherits:false;initial-value:#FF4444;}
@property --lc-c2{syntax:"<color>";inherits:false;initial-value:#3A0F0F;}
@keyframes lc-standby{0%,49.9%{--lc-c1:#FF4444;--lc-c2:#3A0F0F}50%,100%{--lc-c1:#3A0F0F;--lc-c2:#FF4444}}
@keyframes lc-standby-sel{0%,49.9%{--lc-c1:#000;--lc-c2:#B80000}50%,100%{--lc-c1:#B80000;--lc-c2:#000}}
@keyframes lc-wait-cap{0%,49.9%{box-shadow:inset -8px 0 0 #FF4444}50%,100%{box-shadow:inset -8px 0 0 #4A1010}}
@keyframes lc-wait-cap-sel{0%,49.9%{box-shadow:inset -8px 0 0 #990000}50%,100%{box-shadow:inset -8px 0 0 #8A0000}}
[data-sidebar-row]:has(.lucide-circle-dot-dashed){
 background-image:repeating-linear-gradient(90deg,var(--lc-c1) 0 calc(12.5% - 4px),transparent calc(12.5% - 4px) 12.5%,var(--lc-c2) 12.5% calc(25% - 4px),transparent calc(25% - 4px) 25%) !important;
 background-size:calc(100% - 28px) 2px !important;background-position:14px calc(100% - 3px) !important;background-repeat:no-repeat !important;
 animation:lc-standby 2s infinite,lc-wait-cap 2s infinite !important;}
