/* Wrappers behind the composer card: same 26px curve so their dark fill cannot peek out at the corners */
:is([data-chat-composer-form],[data-chat-composer-form] *):has([data-slot="composer-host"]){border-radius:26px !important;}
:is([data-chat-composer-form],[data-chat-composer-form] *):has([data-slot="composer-host"])::before,:is([data-chat-composer-form],[data-chat-composer-form] *):has([data-slot="composer-host"])::after{border-radius:26px !important;}
/* Attached question/banner panel behind the composer: drop its dark shadow and match the frame curve */
[data-composer-banner-surface],[data-composer-banner-surface]::before,[data-composer-banner-surface]::after{box-shadow:none !important;border-radius:26px !important;}
/* Clip everything inside the composer frame to its curve, so inner panels' outlines can't cross the orange corner */
[data-slot="composer-host"]{overflow:clip !important;}
/* Stop button: solid LCARS red, black glyph */
button[aria-label="Stop generation"],button[aria-label="Stopping"]{background:var(--lc-stop,#E04848) !important;color:#000 !important;box-shadow:none !important;}
button[aria-label="Stop generation"]:hover{background:color-mix(in srgb,var(--lc-stop,#E04848) 80%,#fff) !important;}
/* Submit/send not ready yet: LCARS outline in the (alert-aware) accent, solid once ready */
button.bg-message-action:disabled{background:transparent !important;border:2px solid var(--lc-orange) !important;color:var(--lc-orange) !important;opacity:1 !important;box-shadow:none !important;}
/* Pending question card: LCARS title bar, accent radios and number badges (all follow the alert palette) */
[data-slot="composer-host"]:has([data-pending-user-input-toggle]){--primary:var(--lc-orange);--primary-foreground:#000;}
[data-pending-user-input-toggle]{background:none !important;color:var(--lc-orange) !important;border-left:22px solid var(--lc-orange) !important;border-bottom:3px solid var(--lc-orange) !important;border-radius:0 0 0 18px !important;margin:10px 12px 4px !important;width:calc(100% - 24px) !important;max-width:calc(100% - 24px) !important;box-sizing:border-box !important;padding-left:12px !important;font-family:var(--lc-font) !important;text-transform:uppercase;letter-spacing:.08em;font-size:16px;font-weight:500;}
[data-pending-user-input-toggle] *{color:var(--lc-orange) !important;}
[data-slot="composer-host"]:has([data-pending-user-input-toggle]) span[aria-hidden="true"].rounded-full.border{border:2px solid var(--lc-orange) !important;background:transparent !important;}
[data-slot="composer-host"]:has([data-pending-user-input-toggle]) kbd{background:var(--lc-orange) !important;color:#000 !important;border:0 !important;border-radius:999px !important;font-weight:600;}
/* Inner panels inside the composer frame: no outlines of their own (the frame is the outline) */
[data-slot="composer-host"] *:not(button):not(span[aria-hidden="true"].rounded-full){border-color:transparent !important;}
[data-slot="composer-host"] *:not(button):not([data-pending-user-input-toggle]),[data-slot="composer-host"] *::before,[data-slot="composer-host"] *::after{box-shadow:none !important;outline-color:transparent !important;}
[data-slot="composer-host"] *::before,[data-slot="composer-host"] *::after{border-color:transparent !important;}
[data-slot="composer-host"] *:not(button):not(kbd):not([data-pending-user-input-toggle]):not(.rounded-full),[data-slot="composer-host"] *::before,[data-slot="composer-host"] *::after{background-color:transparent !important;backdrop-filter:none !important;}
/* Thread details card: LCARS panel with segmented meters */
[data-thread-details-card]{background:#0A0303 !important;border:2px solid var(--lc-orange) !important;border-left:14px solid var(--lc-lav) !important;border-radius:22px 22px 22px 22px / 22px !important;}
[data-thread-details-card] *{border-color:color-mix(in srgb,var(--lc-lav) 35%,transparent) !important;}
[data-thread-details-card] :is(button,a,[role="button"],[data-slot="button"],[data-slot="select-trigger"]),[data-thread-details-card] :is(button,a,[role="button"],[data-slot="button"]) *{border-color:transparent !important;box-shadow:none !important;background-color:transparent !important;}
[data-thread-details-card] :is(button,a,[role="button"],[data-slot="button"]):hover{background-color:#200808 !important;border-radius:999px !important;}
[data-thread-details-card] svg{color:var(--lc-lav) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span:first-child{font-family:var(--lc-font) !important;text-transform:uppercase;letter-spacing:.08em;font-size:13px;color:var(--lc-peach) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span:last-child{font-family:var(--lc-font) !important;font-size:15px;letter-spacing:.04em;color:var(--lc-orange) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span.relative{height:8px !important;border-radius:2px !important;background:repeating-linear-gradient(90deg,#24243A 0 9px,transparent 9px 12px) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span.relative > span:not([aria-hidden]){border-radius:2px !important;background:repeating-linear-gradient(90deg,var(--lc-orange) 0 9px,transparent 9px 12px) !important;}
[data-thread-details-card] [tabindex="0"][aria-label^="Context:"] > span.relative > span:not([aria-hidden]){background:repeating-linear-gradient(90deg,var(--lc-violet) 0 9px,transparent 9px 12px) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span.relative > span.bg-warning{background:repeating-linear-gradient(90deg,var(--lc-gold) 0 9px,transparent 9px 12px) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span.relative > span.bg-error{background:repeating-linear-gradient(90deg,#FF3333 0 9px,transparent 9px 12px) !important;}
[data-thread-details-card] [tabindex="0"][aria-label*=": "] > span.relative > span[aria-hidden]{background:var(--lc-peach) !important;height:12px !important;top:-2px !important;width:2px !important;}
/* Status rows (working / waiting / input / approval / failed): a card of their own with a square right edge for the endcap */
[data-sidebar-row]:is(:has(.text-info-foreground),:has(.lucide-circle-dot-dashed),:has(.lucide-message-circle-question-mark),:has(.lucide-shield-question-mark),:has(.lucide-circle-alert)){border-radius:14px 4px 4px 14px !important;}
[data-sidebar-row]:is(:has(.text-info-foreground),:has(.lucide-circle-dot-dashed)):not([aria-current="page"]):not([aria-current="true"]){background-color:#140F1C !important;}
/* 2. Status labels readable on dark cards (selected rows still force black) */
[data-sidebar-row] .text-info-foreground{color:var(--lc-orange) !important;}
[data-sidebar-row] :is(span,div):has(> .lucide-message-circle-question-mark){color:#7FD3FF !important;}
/* Ship alert states (fade 1.6s): Input = incoming hail (blue), Approval = yellow alert (amber), Failed = red alert. Most severe wins. */
@property --lc-orange{syntax:"<color>";inherits:true;initial-value:#FF2222;}
@property --lc-peach{syntax:"<color>";inherits:true;initial-value:#FFB3B3;}
@property --lc-lav{syntax:"<color>";inherits:true;initial-value:#B33A3A;}
@property --lc-violet{syntax:"<color>";inherits:true;initial-value:#FF4444;}
@property --lc-blue{syntax:"<color>";inherits:true;initial-value:#FFAAAA;}
@property --lc-gold{syntax:"<color>";inherits:true;initial-value:#FF6666;}
@property --lc-glow{syntax:"<color>";inherits:true;initial-value:rgba(0,0,0,0);}
@property --lc-p{syntax:"<number>";inherits:true;initial-value:1;}
:root{transition:--lc-orange 1.6s ease,--lc-peach 1.6s ease,--lc-lav 1.6s ease,--lc-violet 1.6s ease,--lc-blue 1.6s ease,--lc-gold 1.6s ease,--lc-glow 1.6s ease;}
@keyframes lc-breathe{0%,100%{--lc-p:1}50%{--lc-p:.4}}
/* App buttons that use the message-action color (Submit, send) follow the alert palette */
:root{--message-action:var(--lc-orange) !important;--message-action-hover:var(--lc-peach) !important;}
/* (alert glow is drawn on [data-slot="sidebar-wrapper"] as edge bands; see base CSS) */

/* Incoming hail */
:root:has([data-sidebar-row] .lucide-message-circle-question-mark){--lc-orange:#4FC3F7;--lc-peach:#B3E5FC;--lc-lav:#5C7FC2;--lc-violet:#7FA8FF;--lc-blue:#C8F0FF;--lc-gold:#80DEEA;--lc-glow:rgba(70,170,255,.16);--lc-stop:#4FC3F7;animation:lc-breathe 3s ease-in-out infinite;}
@keyframes lc-hail-cap{0%,100%{box-shadow:inset -8px 0 0 #4FC3F7}50%{box-shadow:inset -8px 0 0 #123A5A}}
[data-sidebar-row]:has(.lucide-message-circle-question-mark){background-color:#0A1A2A !important;animation:lc-hail-cap 2s ease-in-out infinite !important;}
[data-sidebar-row][aria-current]:not([aria-current="false"]):has(.lucide-message-circle-question-mark){background-color:#4FC3F7 !important;animation:lc-hail-cap 2s ease-in-out infinite !important;}

/* Yellow alert */
:root:has([data-sidebar-row] .lucide-shield-question-mark){--lc-orange:#FFB300;--lc-peach:#FFE082;--lc-lav:#C9A227;--lc-violet:#FFD54F;--lc-blue:#FFF1B8;--lc-gold:#FFCA28;--lc-glow:rgba(255,190,0,.24);--lc-stop:#FFB300;animation:lc-breathe 3.5s ease-in-out infinite;}
@keyframes lc-yellow-cap{0%,100%{box-shadow:inset -8px 0 0 #FFB300}50%{box-shadow:inset -8px 0 0 #5A4000}}
@keyframes lc-yellow-cap-sel{0%,100%{box-shadow:inset -8px 0 0 #B37D00}50%{box-shadow:inset -8px 0 0 #FFE9A8}}
[data-sidebar-row]:has(.lucide-shield-question-mark){background-color:#2A2200 !important;animation:lc-yellow-cap 2.4s ease-in-out infinite !important;}
[data-sidebar-row][aria-current]:not([aria-current="false"]):has(.lucide-shield-question-mark){background-color:#FFB300 !important;animation:lc-yellow-cap-sel 2.4s ease-in-out infinite !important;}

/* Red alert */
:root:has([data-sidebar-row] .lucide-circle-alert){--lc-orange:#FF3333;--lc-peach:#FF9E9E;--lc-lav:#B33A3A;--lc-violet:#FF5C5C;--lc-blue:#FFB0B0;--lc-gold:#FF7070;--lc-glow:rgba(255,30,30,.2);--lc-stop:#FF3333;animation:lc-breathe 4s ease-in-out infinite;}
@keyframes lc-red-cap{0%,49.9%{box-shadow:inset -8px 0 0 #FF3333}50%,100%{box-shadow:inset -8px 0 0 #5A0000}}
[data-sidebar-row]:has(.lucide-circle-alert){background-color:#2A0808 !important;animation:lc-red-cap 1.2s infinite !important;}
[data-sidebar-row][aria-current]:not([aria-current="false"]):has(.lucide-circle-alert){background-color:#FF3333 !important;animation:lc-red-cap 1.2s infinite !important;}

@media (prefers-reduced-motion:reduce){:root{transition:none !important;animation:none !important;}[data-sidebar-row][data-sidebar-row]:is(:has(.lucide-message-circle-question-mark),:has(.lucide-shield-question-mark),:has(.lucide-circle-alert)){animation:none !important;}}

/* Red alert pulse */
@keyframes lc-alert-bars{0%,100%{border-color:#FF2222}50%{border-color:#5A0000}}
@keyframes lc-alert-glow{0%,100%{box-shadow:inset 0 0 140px rgba(255,20,20,.16)}50%{box-shadow:inset 0 0 60px rgba(255,20,20,.03)}}
[data-slot="sidebar-inner"]{animation:lc-alert-bars 1.8s ease-in-out infinite;}
[data-slot="composer-host"]{animation:lc-alert-bars 1.8s ease-in-out infinite;}
[data-workspace-area="conversation"]{animation:lc-alert-glow 1.8s ease-in-out infinite,lc-drift 300s steps(1400) infinite;}
[data-workspace-area="conversation"]:is(:root:has(button[aria-label="Stop generation"]) *){animation:lc-alert-glow 1.8s ease-in-out infinite,lc-drift 300s steps(1400) infinite;}
@media (prefers-reduced-motion:reduce){[data-slot="sidebar-inner"],[data-slot="composer-host"],[data-workspace-area="conversation"]{animation:none !important;}}
